/*
 * ld - a small static linker for uClinux on the Macintosh Plus.
 *
 * Generated by LLM
 *
 * Links ELF32 big-endian m68k relocatable objects (written by our as, or by
 * gcc) and ar archives into a bFLT executable (revision 4, loaded entirely
 * into RAM, absolute addressing, no GOT) that binfmt_flat.c can run.
 *
 * usage: ld [-o out] [-L dir] [-s stack] [-M] files.o libs.a -lname ...
 *
 * Image address space as the kernel loader sees it: text starts at 0 (the
 * byte after the 64 byte flat header), data follows the text, bss follows
 * the data. Every 32 bit field that holds an address is written as the
 * link-time address and listed in the relocation table, the loader then adds
 * the real load address.
 *
 * Archive members are selected with the archive's symbol index when there
 * is one, otherwise the members are scanned. Written to be built with gcc
 * 2.95 (C89) as well as a modern host compiler.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HDR_SIZE 64
#define FLAT_FLAG_RAM 1

#define SHT_PROGBITS 1
#define SHT_SYMTAB 2
#define SHT_RELA 4
#define SHT_NOBITS 8
#define SHT_REL 9
#define SHF_WRITE 1
#define SHF_ALLOC 2
#define SHF_EXECINSTR 4
#define SHN_UNDEF 0
#define SHN_ABS 0xfff1
#define SHN_COMMON 0xfff2
#define STB_LOCAL 0
#define STB_WEAK 2
#define STT_SECTION 3

#define R_68K_32 1
#define R_68K_16 2
#define R_68K_8 3
#define R_68K_PC32 4
#define R_68K_PC16 5
#define R_68K_PC8 6
#define R_68K_PLT32 13
#define R_68K_PLT16 14
#define R_68K_PLT8 15

enum { SEG_TEXT = 0, SEG_DATA = 1, SEG_BSS = 2, SEG_NONE = 3 };

struct isect {
    unsigned long off, size, addralign, type, flags, link, info, entsize;
    int seg;
    unsigned long out;      /* offset within the output segment */
};

struct obj {
    char *name;
    unsigned char *img;
    unsigned long len;
    struct isect *sec;
    int nsec;
    int symtab;             /* section index of the symbol table, or -1 */
    unsigned char *syms;
    unsigned long nsyms;
    unsigned char *strs;
};

struct gsym {
    char *name;
    struct gsym *next;
    struct obj *obj;        /* defining object, NULL if not (yet) defined */
    unsigned long idx;
    int referenced;
    int common;             /* defined as common so far */
    unsigned long csize, calign, cout;
    int special;            /* linker defined: value in 'sval' */
    int sseg;
    unsigned long sval;
};

struct entry {              /* archive symbol index entry */
    char *name;
    unsigned long off;
};

struct archive {
    char *name;
    FILE *fp;
    struct entry *ent;
    int nent, capent;
    unsigned long *loaded;
    int nloaded;
};

static struct obj **objs;
static int nobjs, capobjs;
static struct archive *arcs;
static int narcs;
static int errors;
static int verbose_map;
static unsigned long segsize[3];
static unsigned long segbase[3];

#define HSIZE 4096
static struct gsym *htab[HSIZE];
static struct gsym **glist;
static int nglist, capglist;

static void fatal(const char *msg, const char *arg)
{
    fprintf(stderr, "ld: ");
    fprintf(stderr, msg, arg ? arg : "");
    fputc('\n', stderr);
    exit(1);
}

static void *xmalloc(unsigned long n)
{
    void *p = malloc(n ? n : 1);
    if (!p)
        fatal("out of memory", NULL);
    return p;
}

static void *xrealloc(void *p, unsigned long n)
{
    p = realloc(p, n ? n : 1);
    if (!p)
        fatal("out of memory", NULL);
    return p;
}

static char *xstrdup(const char *s)
{
    char *p = xmalloc(strlen(s) + 1);
    strcpy(p, s);
    return p;
}

static unsigned long rd32(const unsigned char *p)
{
    return ((unsigned long)p[0] << 24) | ((unsigned long)p[1] << 16) |
           ((unsigned long)p[2] << 8) | p[3];
}

static unsigned rd16(const unsigned char *p)
{
    return (unsigned)((p[0] << 8) | p[1]);
}

static void wr32(unsigned char *p, unsigned long v)
{
    p[0] = (unsigned char)(v >> 24);
    p[1] = (unsigned char)(v >> 16);
    p[2] = (unsigned char)(v >> 8);
    p[3] = (unsigned char)v;
}

static void wr16(unsigned char *p, unsigned long v)
{
    p[0] = (unsigned char)(v >> 8);
    p[1] = (unsigned char)v;
}

/* ------------------------------------------------------------------ */
/* global symbols                                                      */

static struct gsym *glookup(const char *name, int create)
{
    unsigned h = 0;
    const char *s;
    struct gsym *g;
    for (s = name; *s; s++)
        h = h * 31 + (unsigned char)*s;
    h %= HSIZE;
    for (g = htab[h]; g; g = g->next)
        if (!strcmp(g->name, name))
            return g;
    if (!create)
        return NULL;
    g = xmalloc(sizeof(*g));
    memset(g, 0, sizeof(*g));
    g->name = xstrdup(name);
    g->next = htab[h];
    htab[h] = g;
    if (nglist >= capglist) {
        capglist = capglist ? capglist * 2 : 256;
        glist = xrealloc(glist, capglist * sizeof(*glist));
    }
    glist[nglist++] = g;
    return g;
}

/* ------------------------------------------------------------------ */
/* ELF object reading                                                  */

#define SYM_NAME(o, i)  ((o)->syms + (i) * 16)
#define SYM_NAMEOFF(p)  rd32(p)
#define SYM_VALUE(p)    rd32((p) + 4)
#define SYM_SIZE(p)     rd32((p) + 8)
#define SYM_INFO(p)     ((p)[12])
#define SYM_SHNDX(p)    rd16((p) + 14)

static const char *sym_str(struct obj *o, const unsigned char *p)
{
    return (const char *)o->strs + SYM_NAMEOFF(p);
}

static struct obj *parse_obj(char *name, unsigned char *img, unsigned long len)
{
    struct obj *o;
    unsigned long shoff, shentsize;
    int i;
    if (len < 52 || memcmp(img, "\177ELF", 4) != 0 || img[4] != 1 ||
        img[5] != 2 || rd16(img + 16) != 1 || rd16(img + 18) != 4) {
        fprintf(stderr, "ld: %s: not an ELF32 big-endian m68k object\n", name);
        errors++;
        free(img);
        return NULL;
    }
    o = xmalloc(sizeof(*o));
    memset(o, 0, sizeof(*o));
    o->name = name;
    o->img = img;
    o->len = len;
    o->symtab = -1;
    shoff = rd32(img + 32);
    shentsize = rd16(img + 46);
    o->nsec = rd16(img + 48);
    if (shoff + (unsigned long)o->nsec * shentsize > len) {
        fprintf(stderr, "ld: %s: truncated\n", name);
        errors++;
        return NULL;
    }
    o->sec = xmalloc(o->nsec * sizeof(struct isect));
    for (i = 0; i < o->nsec; i++) {
        unsigned char *h = img + shoff + (unsigned long)i * shentsize;
        struct isect *s = &o->sec[i];
        s->type = rd32(h + 4);
        s->flags = rd32(h + 8);
        s->off = rd32(h + 16);
        s->size = rd32(h + 20);
        s->link = rd32(h + 24);
        s->info = rd32(h + 28);
        s->addralign = rd32(h + 32);
        s->entsize = rd32(h + 36);
        s->seg = SEG_NONE;
        s->out = 0;
        if (s->type != SHT_NOBITS && s->off + s->size > len) {
            fprintf(stderr, "ld: %s: section %d is truncated\n", name, i);
            errors++;
            return NULL;
        }
        if (s->type == SHT_SYMTAB && o->symtab < 0)
            o->symtab = i;
    }
    if (o->symtab >= 0) {
        struct isect *st = &o->sec[o->symtab];
        o->syms = img + st->off;
        o->nsyms = st->size / 16;
        if (st->link < (unsigned long)o->nsec)
            o->strs = img + o->sec[st->link].off;
        else
            o->strs = (unsigned char *)"";
    }
    return o;
}

/* make the global symbols of an object known */
static void enter_globals(struct obj *o)
{
    unsigned long i;
    for (i = 1; i < o->nsyms; i++) {
        unsigned char *p = SYM_NAME(o, i);
        int bind = SYM_INFO(p) >> 4;
        unsigned shndx = SYM_SHNDX(p);
        struct gsym *g;
        if (bind == STB_LOCAL || !*sym_str(o, p))
            continue;
        g = glookup(sym_str(o, p), 1);
        if (shndx == SHN_UNDEF) {
            if (bind != STB_WEAK)
                g->referenced = 1;
            continue;
        }
        if (shndx == SHN_COMMON) {
            unsigned long sz = SYM_SIZE(p), al = SYM_VALUE(p);
            if (g->obj)
                continue;
            g->common = 1;
            if (sz > g->csize)
                g->csize = sz;
            if (al > g->calign)
                g->calign = al;
            continue;
        }
        if (g->obj && !g->common)
            continue;       /* first definition wins */
        g->obj = o;
        g->idx = i;
        g->common = 0;
    }
}

static void add_obj(struct obj *o)
{
    if (!o)
        return;
    if (nobjs >= capobjs) {
        capobjs = capobjs ? capobjs * 2 : 32;
        objs = xrealloc(objs, capobjs * sizeof(*objs));
    }
    objs[nobjs++] = o;
    enter_globals(o);
}

static unsigned char *read_whole(FILE *fp, unsigned long n)
{
    unsigned char *b = xmalloc(n);
    if (fread(b, 1, n, fp) != n)
        fatal("read error", NULL);
    return b;
}

/* ------------------------------------------------------------------ */
/* archives                                                            */

static void add_entry(struct archive *a, const char *name, unsigned long off)
{
    if (a->nent >= a->capent) {
        a->capent = a->capent ? a->capent * 2 : 1024;
        a->ent = xrealloc(a->ent, a->capent * sizeof(struct entry));
    }
    a->ent[a->nent].name = xstrdup(name);
    a->ent[a->nent].off = off;
    a->nent++;
}

static unsigned long hdr_size(const unsigned char *h)
{
    char buf[11];
    memcpy(buf, h + 48, 10);
    buf[10] = 0;
    return (unsigned long)strtoul(buf, NULL, 10);
}

/* build an index by looking into every member */
static void scan_archive(struct archive *a)
{
    unsigned long pos = 8;
    unsigned char h[60];
    fseek(a->fp, 0, SEEK_END);
    for (;;) {
        unsigned long size, i;
        unsigned char *img;
        struct obj *o;
        if (fseek(a->fp, (long)pos, SEEK_SET) != 0 || fread(h, 1, 60, a->fp) != 60)
            break;
        size = hdr_size(h);
        if (h[0] != '/' && memcmp(h, "__.SYMDEF", 9) != 0) {
            img = read_whole(a->fp, size);
            o = parse_obj(xstrdup("?"), img, size);
            if (o) {
                for (i = 1; i < o->nsyms; i++) {
                    unsigned char *p = SYM_NAME(o, i);
                    if ((SYM_INFO(p) >> 4) != STB_LOCAL && SYM_SHNDX(p) != SHN_UNDEF)
                        add_entry(a, sym_str(o, p), pos);
                }
                free(o->sec);
                free(o);
            }
            free(img);
        }
        pos += 60 + size + (size & 1);
    }
}

static void open_archive(char *path)
{
    struct archive *a;
    unsigned char h[60];
    arcs = xrealloc(arcs, (narcs + 1) * sizeof(*arcs));
    a = &arcs[narcs++];
    memset(a, 0, sizeof(*a));
    a->name = path;
    a->fp = fopen(path, "rb");
    if (!a->fp)
        fatal("cannot open %s", path);
    if (fread(h, 1, 8, a->fp) != 8 || memcmp(h, "!<arch>\n", 8) != 0)
        fatal("%s: not an archive", path);
    if (fread(h, 1, 60, a->fp) == 60 && h[0] == '/' && h[1] == ' ') {
        unsigned long size = hdr_size(h), n, i;
        unsigned char *b = read_whole(a->fp, size);
        unsigned char *names;
        n = rd32(b);
        names = b + 4 + n * 4;
        for (i = 0; i < n; i++) {
            add_entry(a, (const char *)names, rd32(b + 4 + i * 4));
            names += strlen((const char *)names) + 1;
        }
        free(b);
    } else {
        scan_archive(a);
    }
}

static int is_loaded(struct archive *a, unsigned long off)
{
    int i;
    for (i = 0; i < a->nloaded; i++)
        if (a->loaded[i] == off)
            return 1;
    return 0;
}

static void load_member(struct archive *a, unsigned long off)
{
    unsigned char h[60];
    unsigned long size;
    unsigned char *img;
    static char name[300], mem[20];
    int n;
    a->loaded = xrealloc(a->loaded, (a->nloaded + 1) * sizeof(unsigned long));
    a->loaded[a->nloaded++] = off;
    fseek(a->fp, (long)off, SEEK_SET);
    if (fread(h, 1, 60, a->fp) != 60)
        fatal("%s: bad archive", a->name);
    size = hdr_size(h);
    memcpy(mem, h, 16);
    mem[16] = 0;
    for (n = 15; n >= 0 && (mem[n] == ' ' || mem[n] == '/' || mem[n] == 0); n--)
        mem[n] = 0;
    if (mem[0] == '/' || !mem[0])
        sprintf(mem, "@%lu", off);
    sprintf(name, "%.200s(%s)", a->name, mem);
    img = read_whole(a->fp, size);
    add_obj(parse_obj(xstrdup(name), img, size));
}

static void pull_members(void)
{
    int progress, k, i;
    do {
        progress = 0;
        for (k = 0; k < narcs; k++) {
            struct archive *a = &arcs[k];
            for (i = 0; i < a->nent; i++) {
                struct gsym *g = glookup(a->ent[i].name, 0);
                if (g && g->referenced && !g->obj && !is_loaded(a, a->ent[i].off)) {
                    load_member(a, a->ent[i].off);
                    progress = 1;
                }
            }
        }
    } while (progress);
}

/* ------------------------------------------------------------------ */
/* layout                                                              */

static unsigned long alignup(unsigned long v, unsigned long a)
{
    return a > 1 ? (v + a - 1) / a * a : v;
}

static void layout(void)
{
    int k, i;
    unsigned long sz[3];
    sz[0] = sz[1] = sz[2] = 0;
    for (k = 0; k < nobjs; k++) {
        struct obj *o = objs[k];
        for (i = 0; i < o->nsec; i++) {
            struct isect *s = &o->sec[i];
            unsigned long al;
            int seg;
            if (!(s->flags & SHF_ALLOC) || (s->type != SHT_PROGBITS && s->type != SHT_NOBITS))
                continue;
            if (s->type == SHT_NOBITS)
                seg = SEG_BSS;
            else if ((s->flags & SHF_WRITE) && !(s->flags & SHF_EXECINSTR))
                seg = SEG_DATA;
            else
                seg = SEG_TEXT;
            al = s->addralign < 2 ? 2 : s->addralign;
            if (al > 4)
                al = 4;
            sz[seg] = alignup(sz[seg], al);
            s->seg = seg;
            s->out = sz[seg];
            sz[seg] += s->size;
        }
    }
    /* common symbols go to the end of bss */
    for (i = 0; i < nglist; i++) {
        struct gsym *g = glist[i];
        if (g->common && !g->obj) {
            unsigned long al = g->calign < 2 ? 2 : g->calign;
            if (al > 4)
                al = 4;
            sz[SEG_BSS] = alignup(sz[SEG_BSS], al);
            g->cout = sz[SEG_BSS];
            sz[SEG_BSS] += g->csize;
        }
    }
    sz[SEG_TEXT] = alignup(sz[SEG_TEXT], 4);
    sz[SEG_DATA] = alignup(sz[SEG_DATA], 4);
    sz[SEG_BSS] = alignup(sz[SEG_BSS], 4);
    segsize[0] = sz[0];
    segsize[1] = sz[1];
    segsize[2] = sz[2];
    segbase[0] = 0;
    segbase[1] = sz[0];
    segbase[2] = sz[0] + sz[1];
}

/* linker defined symbols */
static void define_special(const char *name, int seg, unsigned long val)
{
    struct gsym *g = glookup(name, 0);
    if (!g || g->obj || g->common || !g->referenced)
        return;
    g->special = 1;
    g->sseg = seg;
    g->sval = val;
}

/* ------------------------------------------------------------------ */
/* relocation                                                          */

/* address of symbol; *isaddr tells whether it moves with the load address */
static int sym_addr(struct obj *o, unsigned long idx, unsigned long *addr, int *isaddr)
{
    unsigned char *p = SYM_NAME(o, idx);
    int bind = SYM_INFO(p) >> 4;
    unsigned shndx = SYM_SHNDX(p);
    struct gsym *g;
    if (bind != STB_LOCAL) {
        g = glookup(sym_str(o, p), 0);
        if (!g)
            return 0;
        if (g->special) {
            *addr = segbase[g->sseg] + g->sval;
            *isaddr = 1;
            return 1;
        }
        if (g->common && !g->obj) {
            *addr = segbase[SEG_BSS] + g->cout;
            *isaddr = 1;
            return 1;
        }
        if (!g->obj) {
            if (bind == STB_WEAK) {
                *addr = 0;
                *isaddr = 0;
                return 1;
            }
            return 0;
        }
        o = g->obj;
        p = SYM_NAME(o, g->idx);
        shndx = SYM_SHNDX(p);
    }
    if (shndx == SHN_ABS) {
        *addr = SYM_VALUE(p);
        *isaddr = 0;
        return 1;
    }
    if (shndx == SHN_UNDEF || shndx >= (unsigned)o->nsec) {
        if (shndx == SHN_COMMON && bind == STB_LOCAL)
            return 0;
        return 0;
    }
    if (o->sec[shndx].seg == SEG_NONE) {
        *addr = 0;
        *isaddr = 0;
        return 1;
    }
    *addr = segbase[o->sec[shndx].seg] + o->sec[shndx].out + SYM_VALUE(p);
    *isaddr = 1;
    return 1;
}

static unsigned long *fixups;
static unsigned long nfix, capfix;

static void add_fixup(unsigned long addr)
{
    if (nfix >= capfix) {
        capfix = capfix ? capfix * 2 : 1024;
        fixups = xrealloc(fixups, capfix * sizeof(unsigned long));
    }
    fixups[nfix++] = addr;
}

static int cmp_ul(const void *a, const void *b)
{
    unsigned long x = *(const unsigned long *)a, y = *(const unsigned long *)b;
    return x < y ? -1 : x > y;
}

static unsigned char *outbuf[3];

static void relocate(struct obj *o, int rs)
{
    struct isect *r = &o->sec[rs];
    struct isect *t;
    unsigned long n, i;
    int rela = r->type == SHT_RELA;
    unsigned long ent = rela ? 12 : 8;
    if (r->info >= (unsigned long)o->nsec)
        return;
    t = &o->sec[r->info];
    if (t->seg == SEG_NONE || t->seg == SEG_BSS)
        return;
    n = r->size / ent;
    for (i = 0; i < n; i++) {
        unsigned char *e = o->img + r->off + i * ent;
        unsigned long off = rd32(e), info = rd32(e + 4);
        unsigned long symi = info >> 8;
        int type = (int)(info & 0xff);
        long addend = 0;
        unsigned long S, P;
        int isaddr = 0;
        unsigned char *place;
        int size;
        long v;
        if (off >= t->size) {
            fprintf(stderr, "ld: %s: relocation outside section\n", o->name);
            errors++;
            continue;
        }
        place = outbuf[t->seg] + t->out + off;
        P = segbase[t->seg] + t->out + off;
        switch (type) {
        case R_68K_32: case R_68K_PC32: case R_68K_PLT32: size = 4; break;
        case R_68K_16: case R_68K_PC16: case R_68K_PLT16: size = 2; break;
        case R_68K_8: case R_68K_PC8: case R_68K_PLT8: size = 1; break;
        default:
            fprintf(stderr, "ld: %s: unsupported relocation type %d\n", o->name, type);
            errors++;
            continue;
        }
        if (rela) {
            addend = (long)rd32(e + 8);
        } else if (size == 4) {
            addend = (long)rd32(place);
        } else if (size == 2) {
            addend = (long)(short)rd16(place);
        } else {
            addend = (long)(signed char)place[0];
        }
        if (symi == 0 || symi >= o->nsyms) {
            S = 0;
        } else if (!sym_addr(o, symi, &S, &isaddr)) {
            const char *nm = sym_str(o, SYM_NAME(o, symi));
            fprintf(stderr, "ld: %s: undefined symbol: %s\n", o->name, nm);
            errors++;
            continue;
        }
        switch (type) {
        case R_68K_32:
            v = (long)S + addend;
            wr32(place, (unsigned long)v);
            if (isaddr)
                add_fixup(P);
            break;
        case R_68K_16: case R_68K_8:
            if (isaddr) {
                fprintf(stderr, "ld: %s: %d bit absolute relocation against an address\n",
                        o->name, size * 8);
                errors++;
                break;
            }
            v = (long)S + addend;
            if (size == 2) wr16(place, (unsigned long)v); else place[0] = (unsigned char)v;
            break;
        default:        /* pc relative */
            if (!isaddr && S != 0) {
                /* absolute target: still relative to P in the image */
            }
            v = (long)S + addend - (long)P;
            if (size == 4) {
                wr32(place, (unsigned long)v);
            } else if (size == 2) {
                if (v < -32768L || v > 32767L) {
                    fprintf(stderr, "ld: %s: pc relative 16 bit relocation out of range\n", o->name);
                    errors++;
                }
                wr16(place, (unsigned long)v);
            } else {
                if (v < -128 || v > 127) {
                    fprintf(stderr, "ld: %s: pc relative 8 bit relocation out of range\n", o->name);
                    errors++;
                }
                place[0] = (unsigned char)v;
            }
            break;
        }
    }
}

/* ------------------------------------------------------------------ */

static void usage(void)
{
    fprintf(stderr, "usage: ld [-o out] [-L dir] [-s stack] [-M] files.o libs.a -lname ...\n");
    exit(1);
}

static char *dirs[32];
static int ndirs;

static char *find_lib(const char *name)
{
    int i;
    static char buf[512];
    for (i = 0; i < ndirs; i++) {
        FILE *f;
        sprintf(buf, "%.400s/lib%.60s.a", dirs[i], name);
        f = fopen(buf, "rb");
        if (f) {
            fclose(f);
            return xstrdup(buf);
        }
    }
    fprintf(stderr, "ld: cannot find -l%s\n", name);
    exit(1);
    return NULL;
}

static FILE *open_in(const char *path, unsigned long *len)
{
    FILE *fp = fopen(path, "rb");
    if (!fp)
        fatal("cannot open %s", path);
    fseek(fp, 0, SEEK_END);
    *len = (unsigned long)ftell(fp);
    fseek(fp, 0, SEEK_SET);
    return fp;
}

static void add_input(char *path)
{
    unsigned long len;
    FILE *fp = open_in(path, &len);
    unsigned char magic[8];
    if (fread(magic, 1, 8, fp) == 8 && memcmp(magic, "!<arch>\n", 8) == 0) {
        fclose(fp);
        open_archive(path);
        return;
    }
    fseek(fp, 0, SEEK_SET);
    add_obj(parse_obj(path, read_whole(fp, len), len));
    fclose(fp);
}

int main(int argc, char **argv)
{
    char *outname = "a.out";
    unsigned long stack = 16384;
    char **inputs;
    int ninputs = 0, i, k;
    unsigned char hdr[HDR_SIZE];
    unsigned long reloc_start, text_len, data_len, bss_len;
    FILE *fp;

    inputs = xmalloc((argc + 1) * sizeof(char *));
    for (i = 1; i < argc; i++) {
        char *a = argv[i];
        if (a[0] == '-' && a[1]) {
            char *val = a[2] ? a + 2 : (i + 1 < argc ? argv[i + 1] : NULL);
            int used_next = !a[2];
            switch (a[1]) {
            case 'o': if (!val) usage(); outname = val; if (used_next) i++; break;
            case 'L': if (!val) usage(); if (ndirs < 31) dirs[ndirs++] = val; if (used_next) i++; break;
            case 's': if (!val) usage(); stack = strtoul(val, NULL, 0); if (used_next) i++; break;
            case 'M': verbose_map = 1; break;
            case 'l':
                if (!val) usage();
                inputs[ninputs] = xmalloc(strlen(val) + 3);
                strcpy(inputs[ninputs], "-l");
                strcat(inputs[ninputs], val);
                ninputs++;
                if (used_next) i++;
                break;
            default: usage();
            }
        } else {
            inputs[ninputs++] = a;
        }
    }
    if (ninputs == 0)
        usage();
    for (i = 0; i < ninputs; i++) {
        if (inputs[i][0] == '-' && inputs[i][1] == 'l')
            add_input(find_lib(inputs[i] + 2));
        else
            add_input(inputs[i]);
    }
    if (errors)
        return 1;
    pull_members();
    layout();
    define_special("end", SEG_BSS, segsize[SEG_BSS]);
    define_special("_end", SEG_BSS, segsize[SEG_BSS]);
    define_special("_edata", SEG_DATA, segsize[SEG_DATA]);
    define_special("edata", SEG_DATA, segsize[SEG_DATA]);
    define_special("_etext", SEG_TEXT, segsize[SEG_TEXT]);
    define_special("etext", SEG_TEXT, segsize[SEG_TEXT]);
    define_special("__bss_start", SEG_BSS, 0);

    outbuf[0] = xmalloc(segsize[0] + 4);
    outbuf[1] = xmalloc(segsize[1] + 4);
    memset(outbuf[0], 0, segsize[0] + 4);
    memset(outbuf[1], 0, segsize[1] + 4);
    outbuf[2] = NULL;
    for (k = 0; k < nobjs; k++) {
        struct obj *o = objs[k];
        for (i = 0; i < o->nsec; i++) {
            struct isect *s = &o->sec[i];
            if (s->seg == SEG_TEXT || s->seg == SEG_DATA)
                if (s->type == SHT_PROGBITS && s->size)
                    memcpy(outbuf[s->seg] + s->out, o->img + s->off, s->size);
        }
        for (i = 0; i < o->nsec; i++)
            if (o->sec[i].type == SHT_RELA || o->sec[i].type == SHT_REL)
                relocate(o, i);
    }
    for (i = 0; i < nglist; i++) {
        struct gsym *g = glist[i];
        if (g->referenced && !g->obj && !g->common && !g->special) {
            fprintf(stderr, "ld: undefined symbol: %s\n", g->name);
            errors++;
        }
    }
    {
        struct gsym *g = glookup("_start", 0);
        if (!g || !g->obj) {
            fprintf(stderr, "ld: warning: no _start (crt0.o missing?)\n");
        }
    }
    if (errors)
        return 1;

    qsort(fixups, nfix, sizeof(unsigned long), cmp_ul);
    {
        unsigned long j, m = 0;
        for (j = 0; j < nfix; j++)
            if (j == 0 || fixups[j] != fixups[j - 1])
                fixups[m++] = fixups[j];
        nfix = m;
    }

    text_len = segsize[0];
    data_len = segsize[1];
    bss_len = segsize[2];
    reloc_start = HDR_SIZE + text_len + data_len;
    memset(hdr, 0, sizeof(hdr));
    memcpy(hdr, "bFLT", 4);
    wr32(hdr + 4, 4);
    wr32(hdr + 8, HDR_SIZE);                        /* entry */
    wr32(hdr + 12, HDR_SIZE + text_len);            /* data_start */
    wr32(hdr + 16, HDR_SIZE + text_len + data_len); /* data_end */
    wr32(hdr + 20, HDR_SIZE + text_len + data_len + bss_len);
    wr32(hdr + 24, stack);
    wr32(hdr + 28, reloc_start);
    wr32(hdr + 32, nfix);
    wr32(hdr + 36, FLAT_FLAG_RAM);

    fp = fopen(outname, "wb");
    if (!fp)
        fatal("cannot write %s", outname);
    fwrite(hdr, 1, HDR_SIZE, fp);
    fwrite(outbuf[0], 1, text_len, fp);
    fwrite(outbuf[1], 1, data_len, fp);
    {
        unsigned long j;
        unsigned char b[4];
        for (j = 0; j < nfix; j++) {
            wr32(b, fixups[j]);
            fwrite(b, 1, 4, fp);
        }
    }
    if (fclose(fp) != 0)
        fatal("write error on %s", outname);

    if (verbose_map) {
        printf("text %lu data %lu bss %lu relocs %lu\n", text_len, data_len, bss_len, nfix);
        for (k = 0; k < nobjs; k++)
            printf("  %s\n", objs[k]->name);
    }
    return 0;
}
